import{_ as s,O as a,o as i,c as r,a as o,i as n,f as p}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.24　人口、代际、生命历程与跨地生活","description":"","frontmatter":{"title":"D.24　人口、代际、生命历程与跨地生活","xkChars":767,"xkLessons":{"D.24":{"title":"D.24　人口、代际、生命历程与跨地生活","lead":"人口总量、构成、生命历程与个人选择要分开；同一资料家族的版本标签也不足以保证各张表同步更新。","explanation":["原文定位：第4901—4916行，原站定位/theory/appendix-d/d-24#section-d-24。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“恒等式不是政策目标”。人口库存随出生死亡迁入迁出变化，记账关系只说明数量怎样连接，不决定应该追求多少人口，更不授权对个人身体配置生育义务。生育、不生育及安全养育的条件分别提出规范问题。[T-main]","粗率受人口结构影响，年龄别率、时期总和指标和真实队列结果是不同对象。净迁移为零可掩盖大量进出；年龄结构也不能直接换算每个家庭的照护时数或某机构财政负担，须增加实际支持网络和制度条件。[T-main]","年龄、时期、队列满足年龄=时期−出生队列。由此产生的线性识别问题不因单纯加样本消失；具体阶段冲击、曲率或附加假设下比较仍可研究，不能把识别限制误写成所有生命历程研究不可能。[T-main]","早期经历可能通过当前技能资源影响后续结果。若控制了这些中介，估计问题已改变；历史项残差不显著或为零不能证明历史从未重要。反过来，历史影响存在也不说明未来无法改变。[T-main]","迁移分析分法律身份、愿望、现实可行性和被迫性；过程中的选择条件会变化。被迫离境仍可能在目的地或局部事项有选择，也可能在特定环节没有替代，不可用一个自由/被迫标签填完全部阶段。[T-main]","ILO对自愿的解释同时要求自由知情接受工作与离开自由。因此曾签约不足以单独证明后来持续自愿，是据定义的合理限缩推论；这不等于仅凭未签约或困难处境即可认定强迫劳动，其他要素和适用条件仍须核。[P-ILO]","同一家庭成员可能分别承担汇款、照护、身份和距离限制。继任也有知识、职位、资源、决定权和责任等不同交接；年龄不自然授予权限，新一代可修旧安排，保存记忆不等重复旧生活。[T-main]","原文组织例中总人数未变，经验者退出、新人加入、照护需求增加。人数恒定只是一项数量结果，不能据此宣布知识完全延续和负担不变；需要登记组成、技能、交接和支持条件。[T-main]","真实版本案例：联合国人口司2026年1月19日WPP2024临时更新说明，多哥普查公开数已调整净漏报，人口司此前又调整一次。更正涉及多哥1950—2023估计、2024—2100中方案人口与生命事件数量；生育死亡率、其他情景、其他地点及全球区域汇总未同步改变。[P-UN]","因此只记WPP2024不足以锁定数据状态。应登记具体文件、修订身份、下载日期、国家及情景；这是一项研究核对建议，不是声称联合国要求通用操作规范。未逐单元重算各表，不能补写未经核实的全球差额。[P-UN]","人口转折须定义首次下降、持续下降起段、达到持续条件的确认年，另分自然减少。公共支出下降也不自动表示需要下降，负担可能转给家庭或非同住支持者。连接§5.5.1、5.5.4核聚合识别，§6.12、§9.2核历史与当前条件，§10.7和§15.2.5核跨位置传递与更新。[T-main]","八研究入口分别是24.01生育死亡与人口转型；24.02年龄结构及照护机制；24.03年龄时期队列识别；24.04关键期与累积路径；24.05迁移身份愿望和可行性；24.06继承与组织传承各项交接；24.07人口政策和生殖正义的规范边界；24.08离乡失散归属和跨地生活经验。导航不能代替各领域原始证据。[T-main]"],"argumentSteps":["先确定数量、构成、时间窗和统计对象。","分流量恒等式与政策规范目标。","核时期队列年龄的识别假设及中介控制目标。","逐阶段核迁移意愿、可行性、强制和权限。","跨表记录修订范围，并追负担与知识的实际交接。"],"distinctions":[{"leftTitle":"净迁移","leftText":"迁入减迁出。","rightTitle":"总流动","rightText":"迁入与迁出可同时很大。"},{"leftTitle":"时期指标","leftText":"特定时期率的汇总。","rightTitle":"队列结果","rightText":"一组人实际历程，不能自动互换。"},{"leftTitle":"年龄关系","leftText":"年龄=时期−队列。","rightTitle":"独立识别","rightText":"须额外结构或假设，不靠纯加样本。"},{"leftTitle":"版本家族","leftText":"如WPP2024。","rightTitle":"实际修订范围","rightText":"文件、地点、年份和情景逐项核。"}],"boundaries":["原文教学反例：成员数未变而经验退出、照护需求增加。","原文边界：历史残差被当前中介吸收，不证明早期作用从未发生。","教学反例：迁入100迁出100，净零但有200次方向流量。"],"questions":["净迁移零是否无人移动？","样本更多消除年龄时期队列线性关系吗？","同一版号保证各表同步吗？","生育政策目标能直接决定个人义务吗？"],"diagramPath":"/reading-assets/S-D-24/figures/d24-flow.png","caseLinks":[{"title":"联合国2026年WPP2024多哥临时更正","href":"https://population.un.org/wpp/assets/Files/WPP2024_Release-Note-rev1.pdf"}],"caseNotes":[{"title":"联合国2026年WPP2024多哥临时更正","text":"2026-01-19说明重复净漏报调整及限定修订范围，只更正多哥指定估计和中方案数量，其他情景、地点、全球区域汇总未同步更新。","sourceLabel":"UN Population Division: World Population Prospects 2024 Interim Update","sourceUrl":"https://population.un.org/wpp/assets/Files/WPP2024_Release-Note-rev1.pdf","sourceLocator":"2026-01-19，页1§2四项说明及§3文件清单；页2rev.1标记","boundary":"只核两页发布说明，未逐单元复算数据；不能据家族版号推所有表同状态。","href":"https://population.un.org/wpp/assets/Files/WPP2024_Release-Note-rev1.pdf"}],"sourceRefs":[{"section":"D.24","start_line":4901,"end_line":4916,"startLine":4901,"endLine":4916}],"outputId":"section-d-24","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：净零不等没有迁移","text":"人工人口1000，出生20死亡20，迁入100迁出100，期末仍1000。净迁移0，总进出流量200；不能从库存未变推出成员和知识未变。","assumptions":"同一时间窗，人数记账无遗漏；流量200不是200名不同个人的保证。","boundary":"不由数字推具体迁移动机、强制或政策目标。"},{"title":"教学构造：转折起点与确认时点","text":"人工年末人口100、99、98、97。首次观察下降在第二年；若预设连续三次下降才确认，则第四年才确认该连续过程，起段仍为第二年。","assumptions":"纯人工四年，确认规则事先给定。","boundary":"不把确认年当自然减少年，未给出生死亡分解。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：成员数未变而经验退出、照护需求增加。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：历史残差被当前中介吸收，不证明早期作用从未发生。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：迁入100迁出100，净零但有200次方向流量。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"净迁移零是否无人移动？","answer":"不是，进出可以相抵。","basis":"库存流量。"},{"question":"样本更多消除年龄时期队列线性关系吗？","answer":"不会，仍要识别假设，其他问题仍可研究。","basis":"识别。"},{"question":"同一版号保证各表同步吗？","answer":"不能，需逐文件核修订范围。","basis":"真实案例。"},{"question":"生育政策目标能直接决定个人义务吗？","answer":"统计目标不拥有个人身体，规范理由另论。","basis":"权限边界。"}],"figures":[{"path":"/reading-assets/S-D-24/figures/d24-flow.png","alt":"出生死亡进出相抵，总数不变但流动和构成可变。","caption":"教学构造。"},{"path":"/reading-assets/S-D-24/figures/d24-version.png","alt":"UN2026临时更新多哥指定范围，其他情景汇总未同步。","caption":"据发布说明。"},{"path":"/reading-assets/S-D-24/figures/d24-time.png","alt":"年龄时期队列线性关系，确认时点与起段不同。","caption":"教学关系及构造。"}],"diagramBrief":"三图说明库存流量、联合国局部更新和年龄时期队列。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未逐表比对WPP数据或估计全球差额。","未评估具体迁移者的法律或选择状况。"],"taskId":"S-D-24","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.24，第4901—4916行","claim_support":["人口流量识别、迁移选择、继任、规范边界、转折和八入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-UN","title":"UN Population Division: World Population Prospects 2024 Interim Update","url":"https://population.un.org/wpp/assets/Files/WPP2024_Release-Note-rev1.pdf","source_type":"primary","version_or_date":"2026-01-19，WPP2024 rev.1","locator":"2026-01-19，页1§2四项说明及§3文件清单；页2rev.1标记","claim_support":["多哥普查数重复作净漏报调整导致更正；仅指定国家年份和中方案数量更新，其他情景、地点及全球区域汇总不更新。"],"limits":["本人完整读两页发布说明；未逐项比对数据ZIP，不把说明当所有文件或所有情景同步修订的证据。"],"access_status":"partially_read"},{"id":"P-ILO","title":"ILO: What is forced labour?","url":"https://www.ilo.org/topics-and-sectors/forced-labour-modern-slavery-and-trafficking-persons/what-forced-labour","source_type":"primary","version_or_date":"2026-10-14访问","locator":"The international legal definition of forced labour，定义及三要素第3项（网页54—63行），例外限定74—80行","claim_support":["自愿包括自由知情接受工作及离开的自由；不能以一次签约替代全过程条件核验。"],"limits":["本人读定义及上下文；“曾签约不足”是据定义作的限缩推论，不是网页原句。未判具体合同或个案，强迫劳动还须其他要素及适用规则。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-24/lecture.md","sourcesPath":"/reading-assets/S-D-24/sources.json","sourceSlicePath":"/reading-assets/S-D-24/source/S-D-24.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-24/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-24.md","filePath":"theory/appendix-d/d-24.md"}'),l={name:"theory/appendix-d/d-24.md"};function d(c,e,u,m,f,_){const t=a("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-24" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.24</span><span class="xk-num__gap">　</span></span>人口、代际、生命历程与跨地生活 <a class="header-anchor" href="#section-d-24" aria-label="Permalink to &quot;D.24　人口、代际、生命历程与跨地生活 {#section-d-24}&quot;">​</a></h1><p>正文连接：§5.5.1、5.5.4；§6.12；§9.2；§10.7；§15.2.5。研究入口：24.01—24.08。</p><p>人口库存由出生、死亡和迁入迁出等流量变化，恒等式不是政策目标。粗率、年龄别率、时期总和指标与实际队列结果不同；净迁移为零也可能同时存在大量迁入和迁出。年龄结构不能直接换算每个家庭或机构的真实照护与财政负担。跨文件比较还须核对实际修订范围；同一版号下，国家表、汇总与不同情景可能没有同步更新（联合国人口司，2026）。</p><p>年龄、时期与队列满足明确的线性关系，更多样本不能独自消除由此产生的线性识别问题。具体阶段冲击、曲率和带有额外假设的比较仍可研究。早期经历可能经当前资源与技能作用于以后结果；当前条件充分吸收历史残差，不等于早期作用从未发生，更不意味着今后不可能改变。</p><p>迁移须分法律身份、愿望、实际可行性与被迫性。选择条件可能沿过程改变：曾签约不证明持续自愿（ILO，见“自愿性”释义），被迫离境者可能仍有局部选择，也可能在特定事项上没有可行替代。解释招募、劳动、安置或返回时，按当前问题分别核对相应条件；同一家庭成员可能分别承受汇款、照护、身份和地理限制。继任涉及知识、职位、资源、决定权和责任，不由年龄自然赋权；新一代可以修订旧安排，保存记忆不等要求重复旧生活。</p><p>教学例：组织成员数未变，但经验者退出、新成员进入、照护需求增加。用总人数判断“完全延续”会遗漏知识与负担。人口政策的共同目标不拥有个人身体；生育、不生育和能够安全养育的条件应分别表达为规范问题，不以统计需要对个人配置义务。</p><p>人口转折年取决于问题：首次下降、连续下降的起段年、达到持续条件的确认年和自然减少并非同一时点。早期经历通过当前资源影响以后结果时，控制这些中介会改变估计目标，不能由历史条件残差消失推断早期经历从未重要。公共支出降低也不说明需要减少，还须核对负担是否移给家庭和非同住支持者。</p><p>专题定位：24.01 人口转型、生育与死亡；24.02 年龄结构、老龄化与照护；24.03 队列、时期与年龄效应；24.04 生命历程、关键期与累积优势；24.05 移民、难民、侨民与边界；24.06 代际更替、继承与组织传承；24.07 人口政策与生殖正义；24.08 失散、离乡、归属与跨地生活。</p></div>',1)),n(t,{section:"D.24"}),e[1]||(e[1]=p("div",{class:"theory-source"},null,-1))])}const h=s(l,[["render",d]]);export{g as __pageData,h as default};
